, 1308, 1450, 1334], \"page_id\": 4}], \"content\": \"ESF-1\\u2014Balance Sheet 69\", \"description\": null, \"id\": 27, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1334, 1450, 1358], \"page_id\": 4}], \"content\": \"ESF-2\\u2014Statement of Net Cost 70\", \"description\": null, \"id\": 28, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1393, 441, 1436], \"page_id\": 4}], \"content\": \"SPECIAL REPORTS\", \"description\": null, \"id\": 29, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 1457, 330, 1499], \"page_id\": 4}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 30, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 1499, 1450, 1523], \"page_id\": 4}], \"content\": \"Introduction\\u2014Highway Trust Fund\", \"description\": null, \"id\": 31, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1523, 1450, 1560], \"page_id\": 4}], \"content\": \"TF-6A\\u2014Highway Trust Fund; Highway Account, Mass Transit Account\", \"description\": null, \"id\": 32, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1666, 1450, 1711], \"page_id\": 4}], \"content\": \"GLOSSARY 73\", \"description\": null, \"id\": 33, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1711, 1450, 1735], \"page_id\": 4}], \"content\": \"ORDER FORM FOR TREASURY PUBLICATIONS Inside back cover\", \"description\": null, \"id\": 34, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1747, 1472, 1801], \"page_id\": 4}], \"content\": \"NOTES: Definitions for words shown in italics can be found in the glossary; Detail may not add to totals due to rounding; n.a. = Not available.\", \"description\": null, \"id\": 35, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 189, 1490, 1761], \"page_id\": 5}], \"content\": \"<table><tr><th colspan=\\\"5\\\">Nonquarterly Tables and Reports</th></tr><tr><td colspan=\\\"5\\\">For the convenience of the \\\"Treasury Bulletin\\\" user, nonquarterly tables and reports are listed below along with the issues in which they appear.</td></tr><tr><th></th><th>March</th><th>June</th><th>Sept.</th><th>Dec.</th></tr><tr><td><b>Federal Fiscal Operations</b></td><td></td><td></td><td></td><td></td></tr><tr><td>FFO-5.\\u2014Internal Revenue Receipts by State</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td>FFO-6.\\u2014Customs and Border Protection Collection of Duties, Taxes and Fees by Districts and Ports</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td><b>Special Reports</b></td><td></td><td></td><td></td><td></td></tr><tr><td>Financial Report of the United States Government excerpt</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td><b>Trust Fund Reports:</b></td><td></td><td></td><td></td><td></td></tr><tr><td>Agriculture Disaster Relief Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Airport and Airway Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Black Lung Disability Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Harbor Maintenance Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Hazardous Substance Superfund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Highway Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Inland Waterways Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Leaking Underground Storage Tank Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Nuclear Waste Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Oil Spill Liability Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Patient Centered Outcomes Research Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Reforestation Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Sport Fish Restoration and Boating Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>United States Victims of State Sponsored Terrorism Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Uranium Enrichment Decontamination and Decommissioning Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Vaccine Injury Compensation Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Wool Research, Development, and Promotion Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr></table>\", \"description\": null, \"id\": 0, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [953, 148, 1483, 417], \"page_id\": 6}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1091, 478, 1494, 860], \"page_id\": 6}], \"content\": \"Profile of the Economy Federal Fiscal Operations Federal Debt Fiscal Service Operations Ownership of Federal Securities U.S. Currency and Coin Outstanding and in Circulation\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1423, 99, 1448, 134], \"page_id\": 7}], \"content\": \"1\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [659, 193, 976, 231], \"page_id\": 7}], \"content\": \"Profile of the Economy\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [576, 255, 1055, 292], \"page_id\": 7}], \"content\": \"(Office of Macroeconomic Analysis)\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [705, 318, 929, 354], \"page_id\": 7}], \"content\": \"August 27, 2024\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 384, 373, 420], \"page_id\": 7}], \"content\": \"Introduction\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [188, 457, 1430, 639], \"page_id\": 7}], \"content\": \"Real GDP growth accelerated in the second quarter of 2024 as a resilient labor market continued to support private demand. Labor market strength persisted in the form of real earnings growth as well as an improved labor supply and demand balance\\u2014though the pace of job creation moderated, and the unemployment rate steadily increased. Nonetheless, initial unemployment claims remain near historically low levels.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 674, 1437, 860], \"page_id\": 7}], \"content\": \"In addition to strong economic growth and persistent labor market strength, the second quarter saw renewed progress in reducing both headline and core inflation\\u2014though elevated price levels continue to cool moods among businesses, builders, and consumers. Even so, measures of inflation are now within reasonable range of the Federal Reserve\\u2019s target rate as cooling price growth for non-housing services has helped slow core inflation.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 896, 446, 931], \"page_id\": 7}], \"content\": \"Economic Growth\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [191, 964, 1415, 1108], \"page_id\": 7}], \"content\": \"Real GDP growth accelerated to 3.0 percent at an annual rate in the second quarter of this year, according to the second estimate, more than double the first quarter\\u2019s 1.4 percent pace. Faster growth largely reflected a pick-up in private consumption, as well as a stronger build in private inventories.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 1148, 1443, 1440], \"page_id\": 7}], \"content\": \"Decomposing GDP into smaller components can be helpful in explaining the economy's performance. The four components we consider are: (1) private domestic final purchases (PDFP), the most persistent and stable component of output, consisting of personal consumption expenditures (PCE), business fixed investment (BFI), and residential investment; (2) government consumption and investment; (3) net international purchases (U.S. exports less U.S. imports); and (4) intermediate demand (or the change in private inventories). Examined separately, each component delivers specific information about activity in various sectors that can also be useful in predicting the future path of growth.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 1480, 1424, 1664], \"page_id\": 7}], \"content\": \"The first component, PDFP, is particularly important to analyze: it measures the private sector's capacity to drive self-sustaining growth and, therefore, may signal the direction of future economic performance. In the second quarter, real PDFP growth was 2.9 percent at an annual rate\\u2014or 0.3 percentage points above the first quarter pace\\u2014and accounted for 2.5 percentage points of total GDP growth.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 1700, 1430, 1848], \"page_id\": 7}], \"content\": \"Personal consumption of goods and services picked up to 2.9 percent at an annual rate in the second quarter, after rising by 1.5 percent in the first quarter. PCE made the largest contribution to GDP growth of any component (2.0 percentage points). Purchases of goods rose by 3.0 percent while growth of expenditures on services stepped down to a 2.9 percent advance.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1410, 92, 1454, 137], \"page_id\": 8}], \"content\": \"2\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [182, 193, 1430, 493], \"page_id\": 8}], \"content\": \"BFI grew by 4.6 percent at an annual rate in the second quarter, a touch faster than the 4.4 percent pace in the first quarter. Investment in real equipment surged by 10.8 percent in the second quarter, the fastest rate in over two years, and intellectual property products investment increased for the sixteenth consecutive quarter, rising 2.6 percent. By contrast, spending on business structures declined outright, slipping 1.6 percent after six consecutive quarters of growth. Investment in manufacturing structures has been robust in each quarter of the past three years, but an on-going pull-back in spending on other sectors\\u2019 structures offset the strong performance in factory investment in the second quarter.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [182, 516, 1439, 714], \"page_id\": 8}], \"content\": \"Residential investment, the final component of PDFP, declined 2.0 percent in the second quarter, reflecting a downturn in the construction of single-family homes and multifamily structures. However, the retrenchment following a 16.0 percent surge in the first quarter as well as solid growth during the second half of 2023. Still, the modest downturn in residential investment growth only subtracted 0.1 percentage points from real GDP growth in the second quarter.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [182, 733, 1439, 1120], \"page_id\": 8}], \"content\": \"Of the remaining major components of GDP, net inventory investment and government spending and investment made positive contributions to economic growth in the second quarter. The change in private inventories, which can exhibit wide swings from quarter to quarter, strengthened in the second quarter, contributing 0.8 percentage points to real GDP growth, after paring growth over the two previous quarters. Meanwhile, government spending added 0.2 percentage points to GDP growth, largely reflecting higher spending by the federal government for national defense expenditures. Turning to net exports, the pace of import growth far exceeded that of exports in the second quarter, leaving the trade deficit at its widest in two years. Net exports subtracted 0.8 percentage points from GDP growth in the second quarter, after paring 0.7 percentage points in the first quarter.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [474, 1223, 1127, 1879], \"page_id\": 8}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [665, 1141, 969, 1190], \"page_id\": 8}], \"content\": \"Growth of Real GDP\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [608, 1186, 1022, 1223], \"page_id\": 8}], \"content\": \"(Quarterly percent change at annual rate)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1423, 99, 1448, 125], \"page_id\": 9}], \"content\": \"3\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [189, 264, 563, 299], \"page_id\": 9}], \"content\": \"Labor Markets and Wages\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [184, 332, 1421, 446], \"page_id\": 9}], \"content\": \"Thus far in 2024, the gap between labor demand and supply has narrowed significantly. Labor markets have seen adequate levels of job growth, upward pressure on nominal wage growth has eased, and the number of job openings has neared the number of available workers.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 481, 1412, 811], \"page_id\": 9}], \"content\": \"Over the first seven months of this year, payroll job creation has slowed. After growing by 267,000 jobs per month in the first quarter of 2024, the average pace of payroll job creation slowed to 168,000 per month in the second quarter. In July, job growth slowed to 114,000. In 2024 thus far, job growth has average 203,000, a level considered adequate for the economy. Recent analysis suggests that above-trend immigration\\u2014which was postponed during the pandemic\\u2014has increased the breakeven pace of job growth needed to maintain a stable unemployment rate with population growth. According to the Federal Reserve Bank of Dallas, the upper end of estimates of breakeven job growth is around 200,000 jobs, roughly double the estimated breakeven pace before the pandemic.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 849, 1441, 1221], \"page_id\": 9}], \"content\": \"Alongside slowing payroll growth, the unemployment rate has crept up a bit, though it remains historically low. Since December 2023, the unemployment rate has increased by 0.6 percentage points, reaching 4.3 percent in July; a broader measure, which captures underemployment of the workforce, has risen 0.7 percentage points over the same period to 7.8 percent. Despite these increases, both rates remain relatively low by historical standards. More timely data, unemployment insurance claims, suggest unemployment remains low. As of the latest releases for mid-August, the level of initial unemployment claims has increased by about 17 percent from the end of December, while continuing unemployment claims have drifted up by about 6 percent. Even after recent increases, these readings are only marginally above those in February 2020, just before the start of the COVID-19 pandemic in the United States.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1252, 1435, 1732], \"page_id\": 9}], \"content\": \"Meanwhile, the labor force participation rate (LFPR) has increased, helping to improve labor supply, while the level of job openings has declined, on balance. The overall LFPR has risen 0.2 percentage points on the year through July to 62.7 percent, largely boosted by an increase in the LFPR for prime-age (ages 25-54) workers. The prime-age LFPR itself has risen by 0.8 percentage points so far this year, reaching a 23-year high of 84.0 percent in July. Meanwhile, labor demand\\u2014as measured by job openings (or vacancies)\\u2014has declined by about 8 percent this year, extending a downward which began in March 2022, although the most recent data in May and June (latest available) showed openings have increased modestly since April. The ratio of job vacancies to unemployed workers has gradually declined since the spring of 2022 to more reasonable levels; as of June, there were 1.2 job openings per unemployed worker, down from the pandemic-high of 2.0 vacancies and in line with the pre-pandemic high. The combination of improving supply (via above-trend immigration and higher participation) and more modest trends in job openings attests to an ongoing rebalancing of labor supply and demand.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 1768, 1419, 1919], \"page_id\": 9}], \"content\": \"Measures of wage growth in the private sector stabilized earlier this year but, more recently, have resumed a slowing trend. Looking at twelve-month growth rates of quarterly averages, average hourly earnings grew 4.2 percent in the first quarter of 2024, then slowed to 3.9 percent in the second quarter, and moderated further to 3.6 percent in July\\u2014the slowest yearly pace\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1423, 99, 1448, 125], \"page_id\": 10}], \"content\": \"4\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [184, 196, 1439, 599], \"page_id\": 10}], \"content\": \"since June 2021. These annual rates are considerably below the post-pandemic peak of 5.9 percent in March 2022, but higher than the 3.0 percent rate over 2019. After slowing earlier this year due to a temporary pick-up in inflation, growth in real earnings has improved slightly. Real average hourly earnings were up 0.7 percent over the year through July 2024, up from a 0.6 percent gain over the year through March. Twelve-month gains have averaged about 0.8 percent over the most recent three months through July. An alternative measure of wage growth, the Employment Cost Index (ECI), points to a stabilization of wages pressures in recent quarters. (The ECI controls for employment shares among industries and occupations, making it a better reference for wage growth.) Over the four quarters through June 2024, the ECI for private sector wages and salaries grew 4.2 percent, after rising 4.3 percent in the first quarter. ECI growth has gradually slowed since reaching a 38-year high of 5.2 percent in March 2022.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [674, 674, 951, 705], \"page_id\": 10}], \"content\": \"Payroll Employment\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [472, 714, 1162, 742], \"page_id\": 10}], \"content\": \"(Monthly average for year shown and monthly amounts, in thousands)\", \"description\": null, \"id\": 3, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [355, 742, 1273, 1223], \"page_id\": 10}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [676, 1261, 954, 1292], \"page_id\": 10}], \"content\": \"Unemployment Rate\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [770, 1296, 865, 1329], \"page_id\": 10}], \"content\": \"(Percent)\", \"description\": null, \"id\": 6, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [443, 1327, 1188, 1879], \"page_id\": 10}], \"content\": null, \"description\": null, \"id\": 7, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1419, 101, 1448, 130], \"page_id\": 11}], \"content\": \"5\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [191, 231, 625, 262], \"page_id\": 11}], \"content\": \"Nonfarm Productivity of Labor\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [188, 297, 1435, 514], \"page_id\": 11}], \"content\": \"With the acceleration in real GDP growth, productivity increased in the second quarter of 2024. Nonfarm productivity growth was 2.3 percent, considerably faster than the 0.4 percent increase during the first quarter of this year. The second quarter's more rapid pace reflected a 3.3 percent jump in real output which more than offset a 1.0 percent increase in worker hours. Over the four quarters through Q2, productivity was up 2.7 percent, about double the year-earlier 1.3 percent four-quarter increase. This marked the fifth consecutive four-quarter advance.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 552, 1435, 842], \"page_id\": 11}], \"content\": \"Even with faster productivity growth in the second quarter worker compensation slowed somewhat. Nominal hourly compensation costs in the nonfarm business sector rose 3.3 percent at an annual rate in the second quarter, after a 4.2 percent increase in the first quarter. Worker compensation was up 3.2 percent over the four quarters through 2024 Q2, well down from the 4.9 percent, year-earlier pace. Despite slower nominal gains, further progress in reducing inflation helped preserve wage gains in real terms in the second quarter. Real compensation per hour grew 0.4 percent at an annual rate, matching the first quarter\\u2019s pace, although over the most recent four quarters, real compensation was flat.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 886, 1424, 1106], \"page_id\": 11}], \"content\": \"Productivity gains helped contain cost growth for businesses in the second quarter, after a noticeably acceleration in the first quarter. Unit labor costs, defined as the average cost of labor per unit of output, slowed to 0.9 percent at an annual rate in the second quarter, after a 3.8 percent jump in the first quarter. Over the four quarters through Q2, growth of these costs was 0.5 percent, marking the ninth consecutive quarter of slowing on a four-quarter basis, and the smallest since an identical reading in 2019 Q3.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1219, 902, 1252], \"page_id\": 11}], \"content\": \"Industrial Production, Manufacturing, and Services\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [191, 1287, 1435, 1466], \"page_id\": 11}], \"content\": \"Industrial production\\u2014that is, the output of manufacturing businesses, mining, and utilities\\u2014has generally grown at a lackluster pace for the past two years. In the second quarter of 2024, output at factories, mines, and utilities increased 0.3 percent on average each month. In July, however, monthly output declined and twelve-month output growth was down 0.2 percent, partly reflecting the negative impacts of Hurricane Beryl in the Gulf region.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1506, 1432, 1869], \"page_id\": 11}], \"content\": \"Manufacturing production, which accounts for about three-quarters of all industrial output, has also trended lower since autumn of 2022. Although output ticked up 0.1 percent per month, on average, in the first and second quarters, it fell 0.3 percent in July and was only 0.1 percent higher over the year. Production was pulled lower in part by the impact of Hurricane Beryl as well as a 7.8 percent plunge in automobile production in July. High-tech manufacturing continues to grow, however. For example, output of computers, communications equipment and semiconductors was up 7.3 percent over the year through July. Excluding high-tech and automotive industries, manufacturing remains generally subdued. In the second quarter, output growth increased just 0.1 percent per month on average, and output in July was 0.3 percent higher.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1424, 99, 1446, 130], \"page_id\": 12}], \"content\": \"6\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [184, 196, 1417, 490], \"page_id\": 12}], \"content\": \"Mining output (14 percent of industrial production) tends to fluctuate from month to month but over the three months through July, declined by 0.9 percent and was 1.5 percent lower over the year through July. Although crude oil extraction has increased over the past year, extraction of natural gas declined as did the output of other mining industries. The final component of industrial output is utilities production, which tends to fluctuate due to weather; unseasonable weather in months often causes sharp swings in output from one month to the next. Hurricane Beryl took its toll in July, and utilities production fell by 3.7 percent, pulled down by a hurricane-related 4.3 percent drop in electricity output.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 523, 1433, 783], \"page_id\": 12}], \"content\": \"National surveys of manufacturing businesses continue to signal weak activity, while national surveys for services indicate modest expansion. The Institute for Supply Management's (ISM) manufacturing index rose above the 50-point growth threshold in March 2024 for the first time since late 2022, but the improvement was short-lived, and as of July, the index stood at 46.8, an eight-month low and signaling mild contraction. For the services sector, the ISM's index dipped below the growth threshold of 50 in both April and June but advanced to 51.4 in July. This index has signaled growth in the national services sector in 17 of the last 19 months.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 818, 434, 856], \"page_id\": 12}], \"content\": \"Housing Markets\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [188, 896, 1439, 969], \"page_id\": 12}], \"content\": \"Housing market activity continued to slow on balance through mid-2024, with some loosening in recent months.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 1004, 1433, 1339], \"page_id\": 12}], \"content\": \"This year's downtrend in new construction starts and permits (a signal for future starts) in the single-family and multi-family sectors has intensified. Single-family starts have declined 21.1 percent since the end of last year and were down 14.8 percent over the year through July. Single-family permits have declined 7.5 percent so far this year, and yearly rates turned negative earlier in 2024 with permits down 1.3 percent over the year through July. In the volatile multi-family sector, starts have declined noticeably over the past year or so. Thus far in 2024, starts have dropped 21.0 percent, and over the twelve months through July, were down 18.4 percent. Meanwhile, multi-family permits have declined 9.4 percent so far this year, and are down 15.1 percent over the year through July, portending future weakness in this segment of the market.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 1372, 1443, 1664], \"page_id\": 12}], \"content\": \"Along with declining trends in single-family as well as multi-family construction, the inventory of homes under construction has fallen by 8.3 percent this year through July as more units were completed than began construction. The total inventory of homes under construction\\u2014both single-family and multi-family\\u2014stood at 1.539 million as of July 2024, well down from the record high of 1.710 million reached in October 2022 (data series begins in 1970). Home builder sentiment has deteriorated despite recent declines in mortgage rates. The National Association of Home Builders\\u2019 housing market index declined since April and dropped to an eight-month low of 39 in August.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 1704, 1441, 1890], \"page_id\": 12}], \"content\": \"Meanwhile, home sales remain near lows last seen in the aftermath of the global financial crisis. However, the downtrend in existing home sales has tapered in recent months, and new home sales have trended higher recently. Existing home sales\\u2014which account for a supermajority of all home sales\\u2014have declined on a twelve-month basis every month since summer 2021. In July 2024, existing home sales were 2.5 percent lower year-over-year. Nonetheless, the decline was a\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1423, 99, 1448, 125], \"page_id\": 13}], \"content\": \"7\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [184, 196, 1412, 339], \"page_id\": 13}], \"content\": \"fraction of the largest year-over-year drop in connection with the pandemic\\u201436.7 percent over the year through January 2023. New single-family home sales have trended higher on balance since July 2022 and were up 5.6 percent over the year through July\\u2014though new home sales currently account for only about 15 percent of total home sales.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 380, 1430, 599], \"page_id\": 13}], \"content\": \"Inventories of existing homes available for sale have improved materially in recent months. Months' supply of existing homes for sale rose to 4.1 months in June and stood at 4.0 months in July, a marked improvement from the all-time low of 1.6 months in January 2022. These readings are also above the 2019 average of 3.9 months of supply. Meanwhile, inventories of new homes on the market have trended lower since July 2022 and stood at 7.5 months' supply in July 2024.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 634, 1424, 1040], \"page_id\": 13}], \"content\": \"In very recent months, monthly growth rates of home prices have slowed somewhat, though annual growth rates remain higher over the year. The Case-Shiller 20-city house price index\\u2014which measures sales prices of existing homes\\u2014has risen somewhat slowly this year; in May 2024 (latest data available), the Case-Shiller price index increased 0.3 percent. Over the year ending May 2024, however, the 20-city index was up 6.8 percent, contrasting with the year-earlier, 1.7 percent decline (but well down from the 21.3 percent recent twelve-month peak rate posted in April 2022). The FHFA purchase-only house price index has been slowing since the turn of the year and was roughly flat in May. Nonetheless, over the year through May 2024, the FHFA measure was up 7.0 percent, more than double the 3.0 percent pace over the year through May 2023 (though markedly slower than the peak rate of 18.9 percent posted over the year through February 2022).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1117, 277, 1146], \"page_id\": 13}], \"content\": \"Prices\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [184, 1183, 1412, 1402], \"page_id\": 13}], \"content\": \"Inflation has slowed significantly from its mid-2022 peak. As measured by the consumer price index (CPI) inflation was 2.9 percent over the twelve months through July, the slowest pace since March 2021 and 6.2 percentage points lower than the peak in June 2022, though readings are still elevated relative to pre-pandemic norms. On a monthly basis, inflation readings have trended lower: in July, CPI inflation was 0.2 percent, following a decline of 0.1 percent in June and a flat reading in May.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 1440, 1415, 1695], \"page_id\": 13}], \"content\": \"Energy price inflation was positive in the first half of this year, but over the most recent two months, twelve-month energy inflation has trended lower, standing at just 1.1 percent over the year through July 2024. A variety of factors, bullish and bearish, have buffeted energy markets in recent months, such as widening geopolitical tensions, repeated extensions of OPEC+ production cuts, expectations of a cease-fire in the Israel-Hamas conflict, concerns about future slowing in the U.S. economy, relief over prospects for near-term monetary easing in the U.S., and weak growth in China.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 1735, 1421, 1881], \"page_id\": 13}], \"content\": \"Meanwhile, food price inflation has stabilized near rates observed prior to the pandemic: monthly food inflation has averaged 0.1 percent through July, slowing from the average pace of 0.2 percent during last year\\u2019s third and fourth quarters. Over the year through July, food price inflation was 2.2 percent, less than one-half the 4.9 percent, year-earlier pace.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1424, 99, 1446, 125], \"page_id\": 14}], \"content\": \"8\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [186, 193, 1435, 455], \"page_id\": 14}], \"content\": \"After picking up to an average 0.4 percent during the first four months of this year, core inflation has slowed again, averaging 0.3 percent per month in May, June, and July and matching the rate during the latter half of last year. Core goods prices have been declining since mid-2023, but the pace of deflation has stabilized more recently to 0.1 percent on average during the first half of this year, after declining 0.2 percent per month on average during the latter half of 2023. In July 2024, core goods prices declined 0.3 percent and were 1.8 percent lower on a twelve-month basis.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 486, 1430, 933], \"page_id\": 14}], \"content\": \"Core services inflation, the driving force behind core CPI inflation, has slowed in recent months. In the first four months of the year, core services prices rose an average 0.5 percent per month, but over the most recent three months through July, core services inflation averaged just 0.2 percent per month. Among core services, rent of housing services (rent of primary residential and owners\\u2019 equivalent rent) contributes the largest share of core inflation, although inflation for this component has moderated considerably from the 0.7 percent to 0.8 percent monthly rates seen in the latter half of 2022. Since September 2023, rent of housing has ranged between 0.4 percent and 0.6 percent, save for a 0.2 percent in June\\u2014the lowest monthly rate since mid-2021. In July, rent of housing inflation returned to 0.4 percent. However, even with recent easing, housing inflation remains well above historical norms. Excluding rent of housing, core services inflation remains elevated as slowing of inflation for some core services has been offset by rapid paces in such services as automotive insurance and medical care.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [184, 966, 1430, 1443], \"page_id\": 14}], \"content\": \"Inflation as measured by the PCE price index is the Federal Reserve\\u2019s preferred measure of inflation, and the FOMC\\u2019s 2 percent inflation target is expressed in terms of headline PCE, although core PCE inflation is also taken into consideration. There are notable differences in weights and methodologies between the CPI and the PCE measures. Historically, twelve-month CPI inflation has exceeded PCE inflation by about 0.4 percentage points on average. This year, however, the wedge has widened, reaching 0.8 percentage points in April and averaging 0.6 percentage points through July. The excess wedge was more than explained by differences between the two inflation measures in the weight assigned to owners\\u2019 equivalent rent (OER). The CPI weighs OER more heavily, and persistently strong growth in OER since the autumn of 2021 has accounted for a significant portion of the excess wedge between the CPI and PCE measures. After trending higher earlier in 2024, headline PCE inflation was 2.5 percent over the twelve months through June, or 0.5 percentage points above the FOMC inflation target, while core PCE inflation slowed to 2.6, the slowest rate since March 2021.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1423, 99, 1448, 125], \"page_id\": 15}], \"content\": \"9\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [701, 196, 931, 226], \"page_id\": 15}], \"content\": \"Consumer Prices\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [636, 252, 994, 283], \"page_id\": 15}], \"content\": \"(Percent change from a year earlier)\", \"description\": null, \"id\": 2, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [410, 325, 1202, 983], \"page_id\": 15}], \"content\": null, \"description\": null, \"id\": 3, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [191, 1089, 670, 1122], \"page_id\": 15}], \"content\": \"Consumer and Business Sentiment\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [191, 1157, 1415, 1600], \"page_id\": 15}], \"content\": \"Despite adequate job creation, rising labor force participation, strong household financial positions, and evidence of robust private consumption, consumer and business mood began to flag in the second quarter of 2024 and has remained subdued through the start of the third quarter. The Reuters/Michigan consumer sentiment index declined to 66.4 in July, an eight-month low, before edging up to 67.8 in early August\\u2014the first increase since March\\u2014as a moderate increase in the expectations component offset a further decline in the current conditions index. Consumers registered more positive views about personal finances as well as the five-year outlook and inflation expectations held steady. Consumer confidence in The Conference Board\\u2019s alternative household survey increased in August to 103.3, reflecting small gains in both the present situation and expectations components. Apart from ongoing concerns about elevated prices and interest rates currently, respondents remained relatively uncertain about the outlook for employment and business conditions.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [189, 1634, 1421, 1893], \"page_id\": 15}], \"content\": \"The National Federation of Independent Business\\u2019s (NFIB) small business optimism index has decreased on balance since mid-2021; however, the survey in July indicated the fourth consecutive month of improved optimism as the index rose to its highest level since February 2022. Nonetheless, pessimism among small business owners persists, and while July\\u2019s reading was above the pre-pandemic low, it remains four points below the 50-year average of 98. Owners of small businesses continued to express concerns about the quality of labor, high input costs, and a limited degree of pricing power.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1408, 99, 1448, 130], \"page_id\": 16}], \"content\": \"10\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [191, 264, 638, 299], \"page_id\": 16}], \"content\": \"Federal Budget Deficit and Debt\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [191, 335, 1441, 587], \"page_id\": 16}], \"content\": \"In FY 2023, the deficit increased $320 billion to $1.70 trillion, equal to 6.3 percent of GDP, as lower receipts outweighed decreased spending. Receipts shrank by $457 billion FY 2023, reflecting in part lower capital gains realizations and lower deposits of Federal Reserve earnings. Outlays decreased by $137 billion in FY 2023, partly reflecting the rescission of planned student loan forgiveness and the expiration of the expanded Child Tax Credit, among other provisions. By contrast, outlays for national defense, Social Security, Medicare, and net interest all had large increases.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 627, 1443, 922], \"page_id\": 16}], \"content\": \"So far in FY 2024, federal finances have continued to improve relative to the comparable period in FY 2023. For Fiscal Year to Date (FTYD) 2024, which runs from October 2023 to the present (July 2024), the federal deficit was $1,517 billion, $97 billion lower than in the previous FYTD. Federal receipts were $4,085 billion in FTYD 2024, up $396 billion (10.7 percent) from the same FTYD a year ago, reflecting an increase in income tax receipts. Federal outlays were $5,602 billion, up $299 billion (5.6 percent) from the same FTYD a year ago, due to increased outlays for national defense and net interest payments, as well as somewhat higher spending on Social Security and Medicare and Medicaid payments.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 959, 1401, 1065], \"page_id\": 16}], \"content\": \"In June 2023, the Treasury's borrowing limit was suspended until early 2025. During the first ten months of FY2024, gross federal debt stood at $35.1 trillion while debt held by the public was $27.9 trillion.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1106, 419, 1141], \"page_id\": 16}], \"content\": \"Monetary Policy\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [191, 1176, 1435, 1358], \"page_id\": 16}], \"content\": \"The Federal Open Markets Committee (FOMC) began raising its policy rate at its meeting in March 2022 to address inflationary pressures in the economy. Tightening amounted to 425 basis points that year, followed by another 100 basis points of tightening in 2023. At its most recent meeting on July 30-31, the FOMC maintained its short-term policy rate target (the federal funds rate, or FFR) at 5.25\\u20135.50%, unchanged since mid-2023.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [191, 1398, 1441, 1577], \"page_id\": 16}], \"content\": \"During the post-FOMC meeting press conference on July 31, Chair Powell observed that \\u201cWe\\u2019ve stated that we do not expect that it will be appropriate to reduce the target range for the federal funds rate until we have gained greater confidence that inflation is moving sustainably toward 2 percent. The second quarter\\u2019s inflation readings have added to our confidence, and more good data would further strengthen that confidence.\\u201d\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1472, 101, 1499, 125], \"page_id\": 17}], \"content\": \"11\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [426, 214, 1198, 248], \"page_id\": 17}], \"content\": \"INTRODUCTION: Federal Fiscal Operations\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 273, 794, 544], \"page_id\": 17}], \"content\": \"Budget authority usually takes the form of appropriations that allow obligations to be incurred and payments to be made. Reappropriations are Congressional actions that extend the availability of unobligated amounts that have expired or would otherwise expire. These are counted as new budget authority in the fiscal year of the legislation in which the reappropriation act is included, regardless of when the amounts were originally appropriated or when they would otherwise lapse.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 556, 794, 766], \"page_id\": 17}], \"content\": \"Obligations generally are liquidated by the issuance of checks or the disbursement of cash\\u2014outlays. Obligations may also be liquidated (and outlays recorded) by the accrual of interest on public issues of Treasury debt securities (including an increase in redemption value of bonds outstanding); or by the issuance of bonds, debentures, notes, monetary credits, or electronic payments.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 778, 794, 1082], \"page_id\": 17}], \"content\": \"Refunds of collections generally are treated as reductions of collections, whereas payments for earned-income tax credits in excess of tax liabilities are treated as outlays. Outlays during a fiscal year may be for payment of obligations incurred in prior years or in the same year. Outlays, therefore, flow in part from unexpended balances of prior year budget authority and from budget authority provided for the year in which the money is spent. Total outlays include both budget and off-budget outlays and are stated net of offsetting collections.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1094, 794, 1395], \"page_id\": 17}], \"content\": \"Receipts are reported in the tables as either budget receipts or offsetting collections. They are collections from the public, excluding receipts offset against outlays. These, also called governmental receipts, consist mainly of tax receipts (including social insurance taxes), receipts from court fines, certain licenses, and deposits of earnings by the Federal Reserve system. Refunds of receipts are treated as deductions from gross receipts. Total Government receipts are compared with total outlays in calculating the budget surplus or deficit.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1407, 794, 1895], \"page_id\": 17}], \"content\": \"Offsetting collections from other Government accounts or the public are of a business-type or market-oriented nature. They are classified as either collections credited to appropriations or fund accounts, or offsetting receipts (i.e., amounts deposited in receipt accounts). The former normally can be used without an appropriation act by Congress. These occur in two instances: (1) when authorized by law, amounts collected for materials or services are treated as reimbursements to appropriations. For accounting purposes, earned reimbursements are also known as revenues. These offsetting collections are netted against gross outlays in determining net outlays from such appropriations; and (2) in the three types of revolving funds (public enterprise, intragovernmental, and trust); offsetting collections are netted against spending, and outlays are reported as the net amount.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 273, 1488, 575], \"page_id\": 17}], \"content\": \"Offsetting receipts in receipt accounts cannot be used without appropriation. They are subdivided into three categories: (1) proprietary receipts, or collections from the public, offset against outlays by agency and by function; (2) intragovernmental transactions, or payments into receipt accounts from governmental appropriation or fund accounts. They finance operations within and between Government agencies and are credited with collections from other Government accounts; and (3) offsetting governmental receipts that include foreign cash contributions.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 587, 1488, 830], \"page_id\": 17}], \"content\": \"Intrabudgetary transactions are subdivided into three categories: (1) interfund transactions\\u2014payments are from one fund group (either Federal funds or trust funds) to a receipt account in the other fund group; (2) Federal intrafund transactions\\u2014payments and receipts both occur within the Federal fund group; and (3) trust intrafund transactions\\u2014payments and receipts both occur within the trust fund group.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 842, 1488, 1174], \"page_id\": 17}], \"content\": \"Offsetting receipts are generally deducted from budget authority and outlays by function, subfunction, or agency. There are four types of receipts, however, that are deducted from budget totals as undistributed offsetting receipts. They are: (1) agencies' payments (including payments by off-budget Federal entities) as employers into employees' retirement funds; (2) interest received by trust funds; (3) rents and royalties on the Outer Continental Shelf lands; and (4) other interest (i.e., that collected on Outer Continental Shelf money in deposit funds when such money is transferred into the budget).\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1186, 1488, 1579], \"page_id\": 17}], \"content\": \"The Government has used the unified budget concept set forth in the \\\"Report of the President's Commission on Budget Concepts\\\" as a foundation for its budgetary analysis and presentation since 1969. The concept calls for the budget to include all of the Government's fiscal transactions with the public. Since 1971, however, various laws have been enacted removing several Federal entities from (or creating them outside of) the budget. Other laws have moved certain off-budget Federal entities onto the budget. Under current law, the off-budget Federal entities consist of the two Social Security trust funds, Federal Old-Age and Survivors Insurance and the Federal Disability Insurance Trust Fund, and the Postal Service.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1591, 1488, 1862], \"page_id\": 17}], \"content\": \"Although an off-budget Federal entity's receipts, outlays, and surplus or deficit ordinarily are not subject to targets set by the Congressional resolution, the Balanced Budget and Emergency Deficit Control Act of 1985 [commonly known as the Gramm-Rudman-Hollings Act as amended by the Budget Enforcement Act of 1990 (2 United States Code 900-922)] included off-budget surplus or deficit in calculating deficit targets under that act and in calculating excess deficit. Partly for this reason, attention has focused\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1472, 99, 1499, 123], \"page_id\": 18}], \"content\": \"12\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [142, 191, 796, 255], \"page_id\": 18}], \"content\": \"on both on- and off-budget receipts, outlays and deficit of the Government.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 264, 794, 599], \"page_id\": 18}], \"content\": \"Tables FFO-1, FFO-2, and FFO-3 are published quarterly and cover 5 years of data, estimates for 2 years, detail for 13 months, and fiscal year-to-date data. They provide a summary of data relating to Federal fiscal operations reported by Federal entities and disbursing officers, and daily reports from the FRBs. They also detail accounting transactions affecting receipts and outlays of the Government and off-budget Federal entities and their related effect on assets and liabilities of the Government. Data are derived from the \\\"Monthly Treasury Statement of Receipts and Outlays of the United States Government.\\\"\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 615, 796, 738], \"page_id\": 18}], \"content\": \"Table FFO-1 summarizes the amount of total receipts, outlays, and surplus or deficit, as well as transactions in Federal securities, monetary assets, and balances in Treasury operating cash.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 745, 796, 898], \"page_id\": 18}], \"content\": \"Table FFO-2 includes on- and off-budget receipts by source. Amounts represent income taxes, social insurance taxes, net contributions for other insurance and retirement, excise taxes, estate and gift taxes, customs duties, and net miscellaneous receipts.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 905, 798, 969], \"page_id\": 18}], \"content\": \"Table FFO-3 details on- and off-budget outlays by agency.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 203, 1494, 323], \"page_id\": 18}], \"content\": \"Table FFO-4 summarizes on- and off-budget receipts by source and outlays by function as reported to each major fund group classification for the current fiscal year to date and prior fiscal year to date.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 332, 1495, 606], \"page_id\": 18}], \"content\": \"Table FFO-5 summarizes internal revenue receipts by states and by type of tax. Amounts reported are collections made in a fiscal year. They span several tax liability years because they consist of prepayments (estimated tax payments and taxes withheld by employers for individual income and Social Security taxes), payments made with tax returns and subsequent payments made after tax returns are due or are filed (that is, payments with delinquent returns or on delinquent accounts).\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 608, 1494, 851], \"page_id\": 18}], \"content\": \"Amounts are reported based on the primary filing address provided by each taxpayer or reporting entity. For multistate corporations, the address may reflect only the district where such a corporation reported its taxes from a principal office rather than other districts where income was earned or where individual income and Social Security taxes were withheld. In addition, an individual may reside in one district and work in another.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 867, 1495, 929], \"page_id\": 18}], \"content\": \"Table FFO-6 includes customs collection of duties, taxes, and fees by districts and ports.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [324, 997, 1311, 1082], \"page_id\": 18}], \"content\": \"Budget Results and Financing of the U.S. Government and Third-Quarter Receipts by Source\", \"description\": null, \"id\": 10, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [621, 1089, 1007, 1117], \"page_id\": 18}], \"content\": \"[Source: Office of Tax Analysis, Office of Tax Policy]\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1134, 423, 1169], \"page_id\": 18}], \"content\": \"Third-Quarter Receipts\", \"description\": null, \"id\": 12, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 1174, 798, 1358], \"page_id\": 18}], \"content\": \"The following capsule analysis of budget receipts, by source, for the third quarter of Fiscal Year 2024 supplements fiscal data reported in the June issue of the \\u201cTreasury Bulletin.\\u201d At the time of that issue\\u2019s release, not enough data were available to analyze adequately collections for the quarter.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 1365, 800, 1702], \"page_id\": 18}], \"content\": \"Individual income taxes\\u2014 Individual income tax receipts, net of refunds, were $796.5 billion for the third quarter of Fiscal Year 2024. This is an increase of $132.3 billion over the comparable prior year quarter. Withheld receipts increased by $27.8 billion and non-withheld receipts increased by $78.7 billion during this period. Refunds decreased by $25.8 billion over the comparable Fiscal Year 2023 quarter. There was an increase of $8.5 billion in accounting adjustments between individual income tax receipts and the Social Security and Medicare trust funds over the comparable quarter in Fiscal Year 2023.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 1711, 800, 1834], \"page_id\": 18}], \"content\": \"Corporate income taxes\\u2014 Net corporate income tax receipts were $203.4 billion for the third quarter of Fiscal Year 2024. This is an increase of $37.5 billion compared to the prior year third quarter. The $37.5 billion change is\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1131, 1499, 1230], \"page_id\": 18}], \"content\": \"comprised of an increase of $34.4 billion in estimated and final payments, and a decrease of $3.1 billion in corporate refunds.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1235, 1495, 1570], \"page_id\": 18}], \"content\": \"Employment taxes and contributions\\u2014Employment taxes and contributions receipts for the third quarter of Fiscal Year 2024 were $478.5 billion, an increase of $20.8 billion over the comparable prior year quarter. Receipts to the Federal Old-Age and Survivors Insurance, Federal Disability Insurance, and Federal Hospital Insurance trust funds changed by $7.4 billion, $1.3 billion, and $12.1 billion respectively. There was a $27.4 billion accounting adjustment for prior years employment tax liabilities made in the third quarter of Fiscal Year 2024. There was a $35.9 billion adjustment in the third quarter of Fiscal Year 2023.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1579, 1494, 1796], \"page_id\": 18}], \"content\": \"Unemployment insurance\\u2014Unemployment insurance receipts, net of refunds, for the third quarter of Fiscal Year 2024 were $25.6 billion, an increase of $1.0 billion over the comparable quarter of Fiscal Year 2023. Net State taxes deposited in the U.S. Treasury increased by $1.0 billion to $21.5 billion. Net Federal Unemployment Tax Act taxes did not change significantly from $4.2 billion.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1470, 99, 1499, 123], \"page_id\": 19}], \"content\": \"13\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [403, 196, 1229, 269], \"page_id\": 19}], \"content\": \"Budget Results and Financing of the U.S. Government and Third-Quarter Receipts by Source, continued\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [142, 285, 798, 436], \"page_id\": 19}], \"content\": \"Contributions for other insurance and retirement\\u2014Contributions for other retirement were $2.0 billion for the third quarter of Fiscal Year 2024. This was an increase of $0.3 billion from the comparable quarter of Fiscal Year 2023.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 443, 798, 629], \"page_id\": 19}], \"content\": \"Excise taxes\\u2014 Net excise tax receipts for the third quarter of Fiscal Year 2024 were $22.2 billion, an increase of $2.9 billion over the comparable prior year quarter. Total excise tax refunds for the quarter were $2.0 billion, a decrease of $3.1 billion over the comparable prior year quarter.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 636, 798, 698], \"page_id\": 19}], \"content\": \"Estate and gift taxes\\u2014 Net estate and gift tax receipts were $9.7 billion for the third quarter of Fiscal Year 2024.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 285, 1488, 344], \"page_id\": 19}], \"content\": \"These receipts represent an increase of $3.0 billion over the same quarter in Fiscal Year 2023.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 356, 1488, 474], \"page_id\": 19}], \"content\": \"Customs duties\\u2014 Customs duties net of refunds were $17.9 billion for the third quarter of Fiscal Year 2024. This is a decrease of $1.3 billion over the comparable prior year quarter.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 483, 1488, 634], \"page_id\": 19}], \"content\": \"Miscellaneous receipts\\u2014 Net miscellaneous receipts for the third quarter of Fiscal Year 2024 were $10.3 billion, an increase of $5.3 billion over the comparable prior year quarter. This change is due in part to deposits of earnings by Federal Reserve banks increasing by $1.3 billion.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 719, 1488, 1346], \"page_id\": 19}], \"content\": \"<table><tr><th colspan=\\\"3\\\">Total On- and Off-Budget Results and Financing of the U.S. Government</th></tr><tr><td colspan=\\\"3\\\">[In millions of dollars. Source: \\\"Monthly Treasury Statement of Receipts and Outlays of the United States Government\\\"]</td></tr><tr><th></th><th>Third quarter 2024<br>April - June</th><th>Fiscal year 2024<br>year to date</th></tr><tr><td>Total on- and off-budget results:</td><td></td><td></td></tr><tr><td>Total receipts</td><td>1,566,100</td><td>3,754,199</td></tr><tr><td>On-budget receipts</td><td>1,198,010</td><td>2,791,771</td></tr><tr><td>Off-budget receipts</td><td>368,090</td><td>962,427</td></tr><tr><td>Total outlays</td><td>1,769,667</td><td>5,022,456</td></tr><tr><td>On-budget outlays</td><td>1,449,927</td><td>4,057,489</td></tr><tr><td>Off-budget outlays</td><td>319,740</td><td>964,967</td></tr><tr><td>Total surplus or deficit (-)</td><td>-203,567</td><td>-1,268,258</td></tr><tr><td>On-budget surplus or deficit (-)</td><td>-251,917</td><td>-1,265,718</td></tr><tr><td>Off-budget surplus or deficit (-)</td><td>48,350</td><td>-2,539</td></tr><tr><td>Means of financing:</td><td></td><td></td></tr><tr><td>Borrowing from the public</td><td>98,196</td><td>1,260,431</td></tr><tr><td>Reduction of operating cash</td><td>-2,529</td><td>-120,908</td></tr><tr><td>Other means</td><td>107,901</td><td>128,735</td></tr><tr><td>Total on- and off-budget financing</td><td>203,567</td><td>1,268,258</td></tr></table>\", \"description\": null, \"id\": 8, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [138, 1367, 1488, 1813], \"page_id\": 19}], \"content\": \"<table><tr><th colspan=\\\"4\\\">Third-Quarter Net Budget Receipts by Source, Fiscal Year 2024</th></tr><tr><td colspan=\\\"4\\\">[In billions of dollars. Source: \\\"Monthly Treasury Statement of Receipts and Outlays of the United States Governme