escription\": null, \"id\": 4, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [138, 1711, 1454, 1737], \"page_id\": 4}], \"content\": \"ORDER FORM FOR TREASURY PUBLICATIONS Inside back cover\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1744, 1479, 1806], \"page_id\": 4}], \"content\": \"NOTES: Definitions for words shown in italics can be found in the glossary; Detail may not add to totals due to rounding; n.a. = Not available.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [310, 214, 1321, 288], \"page_id\": 5}], \"content\": \"Nonquarterly Tables and Reports\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [311, 325, 1321, 391], \"page_id\": 5}], \"content\": \"For the convenience of the \\\"Treasury Bulletin\\\" user, nonquarterly tables and reports are listed below along with the issues in which they appear.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [175, 427, 1461, 1638], \"page_id\": 5}], \"content\": \"<table><tr><th></th><th>March</th><th>June</th><th>Sept.</th><th>Dec.</th></tr><tr><td colspan=\\\"5\\\"><b>Federal Fiscal Operations</b></td></tr><tr><td>FFO-5.\\u2014Internal Revenue Receipts by State</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td>FFO-6.\\u2014Customs and Border Protection Collection of Duties, Taxes and Fees by Districts and Ports</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td colspan=\\\"5\\\"><b>Special Reports</b></td></tr><tr><td>Financial Report of the United States Government excerpt</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td colspan=\\\"5\\\">Trust Fund Reports:</td></tr><tr><td>Agriculture Disaster Relief Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Airport and Airway Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Black Lung Disability Trust Fund</td><td>&#10004;</td><td></td><td></td><td>