bbox\": [{\"coord\": [1472, 101, 1508, 125], \"page_id\": 54}], \"content\": \"47\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [375, 212, 1255, 252], \"page_id\": 54}], \"content\": \"INTRODUCTION: Ownership of Federal Securities\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 271, 798, 453], \"page_id\": 54}], \"content\": \"Federal securities presented in the following tables are public debt securities such as savings bonds, bills, notes, and bonds that the Treasury issues. The tables also detail debt issued by other Federal agencies under special financing authorities. [See the Federal debt (FD) tables for a more complete description of the Federal debt.]\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 462, 798, 674], \"page_id\": 54}], \"content\": \"Effective January 1, 2001, Treasury's Bureau of the Fiscal Service revised formats, titles, and column headings in the \\\"Monthly Statement of the Public Debt of the United States,\\\" Table I: Summary of Treasury Securities Outstanding and Table II: Statutory Debt Limit. These changes should reduce confusion and bring the publication more in line with the public's use of terms.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 684, 798, 867], \"page_id\": 54}], \"content\": \"Treasury's Bureau of the Fiscal Service compiles data in the \\\"Treasury Bulletin\\\" table OFS-1 from the \\\"Monthly Statement of the Public Debt of the United States.\\\" Effective June 2001, Bureau of the Fiscal Service revised procedures and categories in this table to agree with the Bureau of the Fiscal Service's publication changes.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 278, 1488, 462], \"page_id\": 54}], \"content\": \"Table OFS-1 presents Treasury marketable and nonmarketable securities and debt issued by other Federal agencies held by Government accounts, the FRBs, and private investors. Social Security and Federal retirement trust fund investments comprise much of the Government account holdings.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 469, 1488, 528], \"page_id\": 54}], \"content\": \"The FRBs acquire Treasury securities in the market as a means of executing monetary policy.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 549, 1490, 820], \"page_id\": 54}], \"content\": \"Table OFS-2 presents the estimated ownership of U.S. Treasury securities. Information is primarily obtained from the Federal Reserve Board of Governors Flow of Funds data, Table L210. State, local, and foreign holdings include special issues of nonmarketable securities to municipal entities and foreign official accounts. They also include municipal, foreign official, and private holdings of marketable Treasury securities. (See footnotes to the table for description of investor categories.)\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1472, 101, 1503, 123], \"page_id\": 55}], \"content\": \"48\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [186, 200, 1433, 229], \"page_id\": 55}], \"content\": \"TABLE OFS-1\\u2014Distribution of Federal Securities by Class of Investors and Type of Issues\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [597, 243, 1025, 266], \"page_id\": 55}], \"content\": \"[In millions of dollars. Source: Bureau of the Fiscal Service]\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [148, 276, 1474, 964], \"page_id\": 55}], \"content\": \"<table><tr><th>End of fiscal year or month</th><th>Total Federal securities outstanding (1)</th><th>Total outstanding (2)</th><th colspan=\\\"3\\\">Public debt securities Held by U.S. Government accounts</th><th>P